*{box-sizing:border-box} :root{font-family:Manrope,Arial,sans-serif;color:#f5f5ef;font-synthesis:none;font-optical-sizing:auto}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101619}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:460px;overflow:hidden;background:#667c75;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,15,16,.5),transparent 25%,transparent 65%,rgba(4,8,9,.48)),linear-gradient(90deg,rgba(7,12,13,.18),transparent 30%,transparent 70%,rgba(7,12,13,.15));z-index:1}.glass{background:rgba(13,20,20,.76);border:1px solid rgba(255,255,255,.13);box-shadow:0 12px 40px rgba(0,0,0,.18);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}.topbar{position:absolute;z-index:3;left:0;right:0;top:0;height:76px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.11);background:linear-gradient(180deg,rgba(11,17,18,.66),rgba(11,17,18,.15));}.brand{display:flex;align-items:center;gap:11px;color:#fff;text-decoration:none;font-size:17px;font-weight:800;letter-spacing:.15em}.brand small{display:block;color:#aab3ae;font-size:8px;font-weight:600;letter-spacing:.29em;margin-top:1px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;background:#d7f45a;color:#142018;font-size:21px;font-weight:800;clip-path:polygon(0 0,100% 0,100% 78%,78% 100%,0 100%)}.top-meta{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:11px;font:10px 'DM Mono',monospace;letter-spacing:.09em;color:rgba(255,255,255,.87)}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c9ec57;box-shadow:0 0 11px #c9ec57}.meta-divider{height:13px;width:1px;background:rgba(255,255,255,.25);margin:0 4px}.weather-icon{font-size:15px;color:#e7edb5}.icon-button{width:38px;height:38px;border:1px solid rgba(255,255,255,.24);background:rgba(255,255,255,.06);border-radius:50%;font-size:17px;cursor:pointer}.mission-card{position:absolute;z-index:2;left:34px;top:104px;width:250px;padding:17px 18px 14px;border-radius:5px}.eyebrow{display:flex;align-items:center;gap:8px;font:9px 'DM Mono',monospace;letter-spacing:.15em;color:#cdd7cb}.eyebrow .live-dot{width:5px;height:5px}.mission-title{font-size:16px;letter-spacing:.06em;font-weight:800;margin-top:13px}.mission-sub{font-size:11px;color:#aab5ae;margin-top:3px}.mission-progress{height:2px;background:rgba(255,255,255,.16);margin-top:16px}.mission-progress span{display:block;width:12%;height:100%;background:#d7f45a;transition:width .3s}.mission-foot{display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;color:#a8b2aa;letter-spacing:.08em;margin-top:8px}.mission-foot span:first-child{color:#e8ebdd}.right-rail{position:absolute;z-index:2;right:28px;top:103px;display:flex;flex-direction:column;align-items:center;gap:9px}.mini-map{position:relative;width:130px;height:130px;border-radius:6px;overflow:hidden;background-color:rgba(16,25,24,.82);margin-bottom:5px}.map-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(185,200,180,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(185,200,180,.08) 1px,transparent 1px);background-size:18px 18px;transform:rotate(-18deg) scale(1.3)}.mini-map svg{position:absolute;inset:0;width:100%;height:100%;fill:none;stroke:#adbd9f;stroke-width:3}.mini-map svg circle{fill:#e2f46b;stroke:#101619;stroke-width:2}.mini-map svg .map-player{fill:#efff95;stroke:none}.map-label{position:absolute;left:57px;top:61px;font:7px 'DM Mono',monospace;letter-spacing:.12em;color:#efff95}.rail-button{position:relative;width:56px;height:53px;border-radius:4px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;background:rgba(15,22,22,.72);cursor:pointer;transition:background .2s,border .2s}.rail-button:hover{background:rgba(49,62,54,.9);border-color:#d7f45a}.rail-button span{font-size:17px;color:#d9ee75}.rail-button small{font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#c5ccc1}.status-led{position:absolute;width:4px;height:4px;right:7px;top:7px;border-radius:50%;background:#53615b}.status-led.on{background:#d7f45a;box-shadow:0 0 7px #d7f45a}.road-sign{position:absolute;right:181px;top:104px;z-index:2;display:flex;align-items:center;gap:10px;padding:9px 13px;border-radius:4px;background:rgba(14,24,23,.74)}.sign-icon{font-size:22px;color:#d7f45a}.road-sign b{font:11px 'DM Mono',monospace;letter-spacing:.12em}.road-sign small{display:block;color:#aab5ac;font:7px 'DM Mono',monospace;letter-spacing:.08em;margin-top:2px}.speed-hud{position:absolute;z-index:2;right:30px;bottom:28px;width:192px;height:112px;padding:13px 15px 10px;border-radius:5px;background:rgba(10,17,18,.82)}.speed-main{display:flex;align-items:baseline;gap:7px}.speed-value{font:500 46px/.9 'DM Mono',monospace;letter-spacing:-.08em;color:#f3f4e9}.speed-unit{font:8px 'DM Mono',monospace;color:#a9b5ad;letter-spacing:.13em}.speed-rule{height:2px;background:rgba(255,255,255,.15);margin:10px 0 8px}.speed-rule span{display:block;width:3%;height:100%;background:#d7f45a;transition:width .15s}.speed-bottom{display:flex;align-items:center;justify-content:space-between;font:9px 'DM Mono',monospace;color:#aeb8af;letter-spacing:.04em}.speed-bottom>span:first-child{color:#d7f45a;font-size:14px}.speed-bottom b{color:#eef0e7;font-weight:500}.status-stack{position:absolute;z-index:2;right:242px;bottom:51px;width:160px;font:8px 'DM Mono',monospace;letter-spacing:.07em;color:#e1e6d9}.status-stack>div:first-child{display:flex;align-items:center;gap:7px}.status-stack b{margin-left:auto;color:#f3f4eb;font-weight:500}.status-icon{color:#d7f45a;font-size:14px}.condition-track{margin-top:8px;height:2px;background:rgba(255,255,255,.25)}.condition-track i{display:block;height:100%;width:100%;background:#d7f45a;transition:width .2s}.controls-hint{position:absolute;z-index:2;left:50%;transform:translateX(-50%);bottom:33px;display:flex;align-items:center;gap:4px;padding:7px 10px;border-radius:4px;background:rgba(13,20,20,.62);color:#e0e5d8}.keycap{width:19px;height:19px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.24);border-radius:3px;font:9px 'DM Mono',monospace;background:rgba(255,255,255,.06)}.hint-copy{font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#b8c2b9;margin:0 6px 0 2px}.hint-sep{height:15px;width:1px;background:rgba(255,255,255,.2);margin:0 6px}.view-chip{position:absolute;z-index:2;left:34px;bottom:34px;font:8px 'DM Mono',monospace;color:#eff4e7;letter-spacing:.1em;text-shadow:0 2px 6px #000}.view-chip span{color:#d7f45a}.action-buttons{display:none}.mobile-controls{display:none}.modal-backdrop{position:absolute;z-index:8;inset:0;background:rgba(4,8,9,.68);display:grid;place-items:center;padding:22px;backdrop-filter:blur(8px)}.modal-backdrop.hidden{display:none}.modal{width:min(820px,94vw);max-height:min(700px,90vh);overflow:auto;border-radius:7px;background:rgba(17,25,25,.96);padding:30px}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid rgba(255,255,255,.12);padding-bottom:18px;margin-bottom:20px}.modal-kicker{font:9px 'DM Mono',monospace;letter-spacing:.17em;color:#d8f16d}.modal h2{margin:6px 0 0;font-size:24px;letter-spacing:-.03em}.modal p{margin:8px 0 0;color:#a9b5ab;font-size:12px}.close-modal{width:33px;height:33px;border:1px solid rgba(255,255,255,.2);background:transparent;border-radius:50%;cursor:pointer}.car-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.car-card{position:relative;text-align:left;min-height:126px;padding:13px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.035);border-radius:4px;cursor:pointer;transition:.18s}.car-card:hover,.car-card.selected{border-color:#d7f45a;background:rgba(215,244,90,.08)}.car-card .car-type{font:8px 'DM Mono',monospace;color:#c9e469;letter-spacing:.13em}.car-card strong{display:block;font-size:13px;margin-top:9px}.car-card small{display:block;color:#9daaa0;font:9px 'DM Mono',monospace;margin-top:5px}.car-silhouette{position:absolute;right:9px;top:35px;width:76px;height:36px;color:rgba(222,239,188,.62)}.garage-layout{display:grid;grid-template-columns:1.1fr 1fr;gap:22px}.preview-panel{position:relative;min-height:260px;display:grid;place-items:center;background:linear-gradient(145deg,#293832,#111918);border:1px solid rgba(255,255,255,.1);overflow:hidden}.preview-panel:after{content:"";position:absolute;bottom:38px;left:10%;width:80%;height:1px;background:rgba(220,240,180,.25);box-shadow:0 14px 35px 2px rgba(0,0,0,.9)}.preview-car{width:86%;height:145px;z-index:1;filter:drop-shadow(0 17px 9px rgba(0,0,0,.6))}.preview-name{position:absolute;z-index:2;bottom:13px;left:15px;font:9px 'DM Mono',monospace;letter-spacing:.12em}.garage-options h3{margin:2px 0 11px;font-size:12px;letter-spacing:.1em}.paint-swatches{display:flex;gap:9px;margin:12px 0 22px}.swatch{width:27px;height:27px;border-radius:50%;border:2px solid rgba(255,255,255,.28);cursor:pointer}.swatch.active{outline:2px solid #d7f45a;outline-offset:3px}.upgrade-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-top:1px solid rgba(255,255,255,.1);font-size:11px}.upgrade-row small{color:#9ba79d;font:9px 'DM Mono',monospace}.primary-btn,.secondary-btn{border:0;border-radius:3px;padding:12px 18px;background:#d7f45a;color:#172018;font-size:10px;font-weight:800;letter-spacing:.12em;cursor:pointer}.secondary-btn{background:rgba(255,255,255,.1);color:#f3f5eb;border:1px solid rgba(255,255,255,.15)}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.weather-options{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.weather-choice{border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.04);border-radius:4px;padding:17px 10px;cursor:pointer}.weather-choice.active{border-color:#d7f45a;background:rgba(215,244,90,.08)}.weather-choice span{display:block;font-size:23px;margin-bottom:9px}.weather-choice b{font-size:11px}.weather-choice small{display:block;color:#9da99f;font-size:9px;margin-top:4px}.toast{position:absolute;z-index:10;left:50%;bottom:110px;transform:translate(-50%,10px);padding:10px 15px;background:rgba(12,18,18,.9);border:1px solid rgba(215,244,90,.45);border-radius:3px;font:9px 'DM Mono',monospace;letter-spacing:.09em;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-overlay{position:absolute;z-index:7;inset:0;display:grid;place-items:center;background:rgba(8,14,14,.48);backdrop-filter:blur(3px)}.pause-overlay.hidden{display:none}.pause-card{text-align:center}.pause-card h2{font-size:32px;letter-spacing:.12em;margin:0 0 8px}.pause-card p{color:#b4beb4;font-size:12px;margin:0 0 22px}.touching{background:rgba(215,244,90,.27)!important;border-color:#d7f45a!important}
@media(max-width:760px){.topbar{height:61px;padding:0 16px}.brand{font-size:14px}.brand-mark{width:30px;height:30px}.top-meta{font-size:8px;gap:6px;white-space:nowrap;top:73px;left:50%;padding:7px 10px;background:rgba(13,20,20,.55);border-radius:3px}.mission-card{left:13px;top:110px;width:205px;padding:12px}.mission-title{font-size:13px;margin-top:9px}.mission-sub{font-size:9px}.mission-progress{margin-top:11px}.mission-foot{font-size:7px}.right-rail{right:12px;top:110px;gap:6px}.mini-map{width:86px;height:86px}.rail-button{width:42px;height:42px}.rail-button span{font-size:14px}.rail-button small{font-size:6px}.road-sign{top:210px;right:12px;padding:7px 9px;gap:6px}.road-sign small{font-size:6px}.road-sign b{font-size:9px}.speed-hud{right:12px;bottom:112px;width:140px;height:87px;padding:9px 11px}.speed-value{font-size:36px}.speed-rule{margin:7px 0 6px}.speed-bottom{font-size:7px}.status-stack{right:auto;left:14px;bottom:130px;width:125px;font-size:7px}.view-chip{left:14px;bottom:94px;font-size:7px}.controls-hint{display:none}.mobile-controls{position:absolute;z-index:3;bottom:12px;left:12px;right:12px;display:flex;justify-content:center;gap:9px}.mobile-controls button{width:54px;height:48px;border:1px solid rgba(255,255,255,.22);border-radius:5px;background:rgba(12,19,19,.68);font-size:17px;touch-action:none}.mobile-controls button[data-control="gas"]{background:rgba(215,244,90,.2);color:#eaff97}.action-buttons{position:absolute;z-index:3;left:12px;right:12px;bottom:70px;display:flex;gap:8px}.action-button{flex:1;display:flex;align-items:center;justify-content:center;gap:5px;height:34px;border:1px solid rgba(255,255,255,.2);background:rgba(12,19,19,.65);border-radius:4px}.action-button span{font-size:14px;color:#d7f45a}.action-button small{font:7px 'DM Mono',monospace;letter-spacing:.05em}.modal{padding:21px 17px}.modal h2{font-size:20px}.car-grid{grid-template-columns:repeat(2,1fr);gap:7px}.car-card{min-height:102px;padding:10px}.car-card strong{font-size:11px;max-width:85px}.car-card small{font-size:8px}.car-silhouette{width:55px;top:34px}.garage-layout{grid-template-columns:1fr}.preview-panel{min-height:170px}.preview-car{height:100px}.weather-options{grid-template-columns:repeat(2,1fr)}.status-stack{bottom:128px}.modal-backdrop{padding:10px}.modal{max-height:92vh}}
@media(max-height:600px) and (min-width:761px){.mission-card{top:85px}.right-rail{top:85px}.mini-map{width:105px;height:105px}.speed-hud{bottom:14px}.status-stack{bottom:35px}.controls-hint{bottom:14px}.view-chip{bottom:18px}.road-sign{top:86px}}

const canvas=document.querySelector('#scene');
const ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s);
const cars=[
 ['Mahindra Scorpio-N','SUV','INDIAN SERIES'],['Toyota Fortuner Legender','SUV','INDIAN SERIES'],['Land Rover Defender','OFF-ROAD','ADVENTURE'],['Mahindra Thar','OFF-ROAD','ADVENTURE'],['Toyota Land Cruiser','OFF-ROAD','ADVENTURE'],['BMW X7','LUXURY SUV','PRESTIGE'],['Mercedes-Benz G-Wagon','LUXURY SUV','PRESTIGE'],['Range Rover','LUXURY SUV','PRESTIGE'],['Porsche Cayenne','SPORT SUV','PERFORMANCE'],['Jeep Wrangler','OFF-ROAD','ADVENTURE'],['Lamborghini Urus','SPORT SUV','PERFORMANCE'],['Toyota Supra','SPORTS','PERFORMANCE'],['Mahindra Scorpio Classic','SUV','INDIAN SERIES'],['Toyota Innova Crysta','MPV','INDIAN SERIES'],['Toyota Hilux','PICKUP','ADVENTURE'],['Ford Endeavour','SUV','INDIAN SERIES'],['Tata Safari','SUV','INDIAN SERIES'],['Tata Harrier','SUV','INDIAN SERIES'],['Maruti Suzuki Jimny','OFF-ROAD','ADVENTURE'],['Nissan GT-R','SPORTS','PERFORMANCE'],['BMW M5','SPORTS SEDAN','PERFORMANCE'],['Mercedes-Benz AMG G63','LUXURY SUV','PRESTIGE'],['Audi RS Q8','SPORT SUV','PERFORMANCE'],['Porsche 911 GT3 RS','SPORTS','PERFORMANCE'],['Lamborghini Aventador','SUPERCAR','PERFORMANCE'],['Ferrari F40','SUPERCAR','LEGENDS'],['McLaren 720S','SUPERCAR','PERFORMANCE'],['Rolls-Royce Cullinan','LUXURY SUV','PRESTIGE'],['Bentley Bentayga','LUXURY SUV','PRESTIGE'],['Bugatti Chiron','HYPERCAR','LEGENDS']
];
const paintColors=['#b8c5b8','#d8e85e','#bd3d32','#1c2528','#e7e2d5','#4a72a0','#b68a53'];
const state={w:innerWidth,h:innerHeight,dpr:1,last:0,velocity:0,steer:0,offset:0,distance:0,fuel:92,condition:100,car:0,color:paintColors[0],camera:0,weather:'Clear',time:8.7,lights:false,indicator:0,indicatorTimer:0,manual:false,gear:1,paused:false,route:'CITY',mission:'FREE DRIVE',upgrade:0,damageFlash:0,hornUntil:0,traffic:[],toastTimer:0,audio:null};
const input={left:false,right:false,gas:false,brake:false};
let curve=0,roadTravel=0,elapsed=0;
function resize(){state.dpr=Math.min(devicePixelRatio||1,2);state.w=innerWidth;state.h=innerHeight;canvas.width=Math.floor(state.w*state.dpr);canvas.height=Math.floor(state.h*state.dpr);canvas.style.width=state.w+'px';canvas.style.height=state.h+'px';ctx.setTransform(state.dpr,0,0,state.dpr,0,0)}
addEventListener('resize',resize);resize();
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function lerp(a,b,t){return a+(b-a)*t}function rand(a,b){return a+Math.random()*(b-a)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function getCar(){return cars[state.car]}function isSUV(){return /SUV|OFF-ROAD|PICKUP|MPV/.test(getCar()[1])}
function speedMax(){return (isSUV()?190:270)+state.upgrade*18}
function initTraffic(){state.traffic=[];for(let i=0;i<9;i++)state.traffic.push({z:rand(.13,.96),x:rand(-.8,.8),speed:rand(.18,.58),color:['#d4d7cb','#bb6147','#506b72','#d0ae54','#252c2b','#a9b7ac'][i%6],kind:i%4===0?'truck':'car'})}
initTraffic();
function roadCenter(y){const horizon=state.h*.33;const d=clamp((y-horizon)/(state.h-horizon),0,1);return state.w*.5+Math.sin(roadTravel*.0008+d*3.1)*state.w*.10*d+Math.sin(roadTravel*.0013+d*6)*state.w*.025*d}
function roadHalf(y){const horizon=state.h*.33,d=clamp((y-horizon)/(state.h-horizon),0,1);return lerp(state.w*.025,state.w*.43,d)}
function drawSky(){const w=state.w,h=state.h,horizon=h*.33;const night=state.time<5.5||state.time>19.5;const dusk=(state.time>17.4&&state.time<19.5)||(state.time>5&&state.time<7);let top=night?'#111d2a':dusk?'#b77357':'#79a7aa',bottom=night?'#465564':dusk?'#efaa75':'#d9c99e';let g=ctx.createLinearGradient(0,0,0,horizon);g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,w,horizon+2);
 if(!night){const sunX=w*(state.time>12?.76:.22),sunY=horizon*.42;let glow=ctx.createRadialGradient(sunX,sunY,2,sunX,sunY,Math.min(w,h)*.15);glow.addColorStop(0,'rgba(255,235,174,.48)');glow.addColorStop(1,'rgba(255,235,174,0)');ctx.fillStyle=glow;ctx.fillRect(sunX-h*.2,sunY-h*.2,h*.4,h*.4);ctx.fillStyle='rgba(255,235,184,.8)';ctx.beginPath();ctx.arc(sunX,sunY,Math.max(8,w*.009),0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='rgba(239,244,218,.75)';ctx.beginPath();ctx.arc(w*.78,horizon*.22,10,0,Math.PI*2);ctx.fill();for(let i=0;i<48;i++){let x=(i*173+31)%w,y=(i*67+11)%(horizon*.7);ctx.fillStyle=`rgba(255,255,255,${.25+(i%4)*.1})`;ctx.fillRect(x,y,1.3,1.3)}}
 // layered distant hills
 for(let layer=0;layer<3;layer++){const y=horizon*(.76+layer*.09),amp=horizon*(.08+layer*.025),shift=roadTravel*(.00006+layer*.000025);ctx.beginPath();ctx.moveTo(0,horizon);for(let x=0;x<=w+10;x+=12){let yy=y+Math.sin(x*.008+shift+layer)*amp+Math.sin(x*.021-shift*.5)*amp*.3;ctx.lineTo(x,yy)}ctx.lineTo(w,horizon);ctx.closePath();ctx.fillStyle=night?['#29383b','#30443f','#3c5044'][layer]:['#7c927e','#71856d','#637d64'][layer];ctx.fill()}
 // far skyline and roadside silhouettes
 if(state.route==='MOUNTAIN'){for(let i=0;i<11;i++){let x=i*w/9-w*.1+((roadTravel*.04)%100),peak=horizon*(.22+(i%4)*.1);ctx.fillStyle=night?'#24383a':'#748775';ctx.beginPath();ctx.moveTo(x-110,horizon*.86);ctx.lineTo(x,peak);ctx.lineTo(x+140,horizon*.86);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(230,235,211,.45)';ctx.beginPath();ctx.moveTo(x,peak);ctx.lineTo(x-17,peak+27);ctx.lineTo(x+4,peak+20);ctx.lineTo(x+23,peak+34);ctx.closePath();ctx.fill()}}else{for(let i=0;i<26;i++){let x=(i*97-roadTravel*.022)%(w+100);if(x<0)x+=w+100;x-=50;let bh=12+(i*31%38);ctx.fillStyle=night?'#293739':'#8c9782';ctx.fillRect(x,horizon-bh,24+(i%3)*13,bh);if(!night&&i%3===0){ctx.fillStyle='rgba(243,224,163,.45)';for(let yy=horizon-bh+5;yy<horizon-3;yy+=7)ctx.fillRect(x+5,yy,3,3)}}}
}
function drawRoad(){const h=state.h,w=state.w,hor=h*.33;let grass=ctx.createLinearGradient(0,hor,0,h);grass.addColorStop(0,state.route==='MOUNTAIN'?'#586453':'#68795a');grass.addColorStop(1,state.route==='MOUNTAIN'?'#3f5142':'#697446');ctx.fillStyle=grass;ctx.fillRect(0,hor,w,h-hor);let points=[];for(let i=0;i<=30;i++){let y=lerp(hor-2,h+12,i/30);points.push({y,c:roadCenter(y),half:roadHalf(y)})}ctx.beginPath();ctx.moveTo(points[0].c-points[0].half-10,points[0].y);for(const p of points)ctx.lineTo(p.c-p.half,p.y);for(let i=points.length-1;i>=0;i--)ctx.lineTo(points[i].c+points[i].half,points[i].y);ctx.closePath();let road=ctx.createLinearGradient(0,hor,0,h);road.addColorStop(0,'#444a48');road.addColorStop(1,'#292f2f');ctx.fillStyle=road;ctx.fill();
 // shoulder and edge lines
