 else if(kind==='tune'){modal.innerHTML=`<div class="modal-head"><div><div class="modal-kicker">GARAGE · CUSTOMIZATION</div><h2>${getCar()[0]}</h2><p>Set up your machine for the roads ahead.</p></div><button class="close-modal" data-action="close">×</button></div><div class="garage-layout"><div class="preview-panel"><svg class="preview-car" viewBox="0 0 360 170"><ellipse cx="180" cy="136" rx="142" ry="20" fill="#000" opacity=".4"/><path d="M40 118l11-35 42-11 38-34h107l42 30 33 11 13 39-12 13H52z" fill="${state.color}" stroke="#d7e3ce" stroke-opacity=".35" stroke-width="3"/><path d="M142 43l-35 34h145l-29-34z" fill="#566865"/><path d="M122 80h142" stroke="#17201e" stroke-width="6"/><circle cx="98" cy="128" r="22" fill="#121817" stroke="#717c71" stroke-width="5"/><circle cx="270" cy="128" r="22" fill="#121817" stroke="#717c71" stroke-width="5"/></svg><span class="preview-name">${getCar()[0].toUpperCase()}</span></div><div class="garage-options"><h3>BODY COLOUR</h3><div class="paint-swatches">${paintColors.map(c=>`<button class="swatch ${state.color===c?'active':''}" data-color="${c}" style="background:${c}" aria-label="Paint ${c}"></button>`).join('')}</div><h3>PERFORMANCE</h3><div class="upgrade-row"><span>Engine mapping</span><small>STAGE ${state.upgrade+1}</small></div><div class="upgrade-row"><span>Top speed</span><small>+${state.upgrade*18} KM/H</small></div><div class="upgrade-row"><span>Handling assist</span><small>${state.upgrade?'SPORT':'STREET'}</small></div><button class="secondary-btn" data-action="upgrade" style="width:100%;margin-top:12px">${state.upgrade?'UPGRADE INSTALLED ✓':'INSTALL PERFORMANCE KIT · ₹25,000'}</button></div></div><div class="modal-actions"><button class="secondary-btn" data-action="collection">CAR COLLECTION</button><button class="primary-btn" data-action="drive">BACK TO THE ROAD →</button></div>`;}
 else if(kind==='weather'){modal.innerHTML=`<div class="modal-head"><div><div class="modal-kicker">ROAD CONDITIONS</div><h2>Set the scene.</h2><p>Weather changes visibility and grip. Find your conditions.</p></div><button class="close-modal" data-action="close">×</button></div><div class="weather-options">${[['Clear','☀','Golden hour skies'],['Rain','☂','Wet roads'],['Storm','ϟ','Low visibility'],['Fog','≋','Misty morning']].map(([n,icon,desc])=>`<button class="weather-choice ${state.weather===n?'active':''}" data-weather="${n}"><span>${icon}</span><b>${n.toUpperCase()}</b><small>${desc}</small></button>`).join('')}</div><div class="modal-head" style="margin:23px 0 0;padding:16px 0 0"><div><div class="modal-kicker">ROUTE SELECT</div><h2 style="font-size:16px">Choose your road.</h2></div></div><div class="weather-options">${[['CITY','▦','Mumbai streets'],['HIGHWAY','↗','NH 48 expressway'],['MOUNTAIN','⌁','Rohtang Pass · mission']].map(([n,icon,desc])=>`<button class="weather-choice ${state.route===n?'active':''}" data-route="${n}"><span>${icon}</span><b>${n}</b><small>${desc}</small></button>`).join('')}</div><div class="modal-actions"><button class="primary-btn" data-action="close">APPLY & DRIVE →</button></div>`;}
 else if(kind==='pause'){modal.innerHTML=`<div class="modal-head"><div><div class="modal-kicker">DRIVE PAUSED · ${getCar()[0].toUpperCase()}</div><h2>Take a moment.</h2><p>Your road is waiting.</p></div><button class="close-modal" data-action="close">×</button></div><div class="weather-options"><button class="weather-choice" data-action="resume"><span>▶</span><b>RESUME DRIVE</b><small>Back on the road</small></button><button class="weather-choice" data-action="garage"><span>▣</span><b>YOUR GARAGE</b><small>Change or tune car</small></button><button class="weather-choice" data-action="weather"><span>◉</span><b>ROAD & WEATHER</b><small>Pick a new route</small></button><button class="weather-choice" data-action="multiplayer"><span>◎</span><b>CREW DRIVE</b><small>Invite a friend locally</small></button></div><div class="modal-actions"><button class="secondary-btn" data-action="close">CONTINUE</button></div>`;}}
function closeModal(){ $('#modalBackdrop').classList.add('hidden');state.paused=false }
$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop'){closeModal();return}const el=e.target.closest('[data-action],[data-car],[data-weather],[data-route],[data-color]');if(!el)return;if(el.dataset.car!==undefined){state.car=+el.dataset.car;toast(`${getCar()[0].toUpperCase()} SELECTED`);openModal('garage');return}if(el.dataset.weather){state.weather=el.dataset.weather;openModal('weather');return}if(el.dataset.route){state.route=el.dataset.route;state.mission=state.route==='MOUNTAIN'?'MOUNTAIN RUN':state.route==='HIGHWAY'?'NIGHT EXPRESS':'FREE DRIVE';openModal('weather');return}if(el.dataset.color){state.color=el.dataset.color;openModal('tune');return}switch(el.dataset.action){case'close':closeModal();break;case'drive':closeModal();ensureAudio();break;case'garage':openModal('garage');break;case'collection':openModal('garage');break;case'tune':openModal('tune');break;case'weather':openModal('weather');break;case'resume':closeModal();break;case'upgrade':if(state.upgrade<3){state.upgrade++;toast('PERFORMANCE KIT INSTALLED')}openModal('tune');break;case'multiplayer':toast('CREW DRIVE · SHARE THIS SCREEN WITH A FRIEND');break}});

