function ensureAudio(){if(state.audio)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ac=new AC(),osc=ac.createOscillator(),gain=ac.createGain();osc.type='sawtooth';osc.frequency.value=65;gain.gain.value=0;osc.connect(gain);gain.connect(ac.destination);osc.start();state.audio={ctx:ac,osc,gain}}catch{}}
function horn(){ensureAudio();if(!state.audio)return;const ac=state.audio.ctx;ac.resume();for(const f of [350,440]){const o=ac.createOscillator(),g=ac.createGain();o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,ac.currentTime);g.gain.exponentialRampToValueAtTime(.07,ac.currentTime+.035);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.42);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.44)}state.hornUntil=elapsed+.42;toast('HORN')}
