function toggleLights(){state.lights=!state.lights;toast(state.lights?'HEADLIGHTS ON':'HEADLIGHTS OFF')}
function toggleIndicator(dir){state.indicator=state.indicator===dir?0:dir;state.indicatorTimer=state.indicator?4:0;toast(state.indicator<0?'LEFT INDICATOR':'RIGHT INDICATOR')}
function toggleManual(){state.manual=!state.manual;state.gear=1;toast(state.manual?'MANUAL TRANSMISSION':'AUTOMATIC TRANSMISSION')}
function gearUp(){if(state.manual)state.gear=clamp(state.gear+1,1,6)}function gearDown(){if(state.manual)state.gear=clamp(state.gear-1,1,6)}
